    "sourceGerman": "Studierende der Geisteswissenschaften werden oft ((gefragt)) ,was sie nach ihrem Studium beruflich einmal machen wollen. Da lohnt sich die Frage, wo denn ((jene)) heute arbeiten, die Seminare ,Vorlesungen und Prüfungen bereits erfolgreich ((hinter)) sich gelassen haben. Über das Programm „Ein Tag mit \" können Studierende einen ((Einblick)) in das Arbeitsleben von Alumni ihres Studienganges bekommen. „Es hat mir viel Mut ((gemacht)) zu sehen, dass ich mit meine. Studiengang auf jeden Fall genug Kompetenzen ((gesammelt))/(erworben) habe, um nach meinem Abschluss einen Job zu bekommen, erzählt Vivienne, die im vierten Master-Semester Anglistik studiert Sie hat(( im)) Rahmen von „Ein Tag mit“ der Anglistik-Alumni Magdalena Kaminskat bei ihrer Arbeit als ((systemischer* )) Coach im Wissenschaftsbereich über die Schulter geschaut. ((Zusammengeführt)) wurden beide durch die Mentorinnen der Philologischen Fakultät und das zentrale Alumni Büro der Universität Leipzig. Es ist uns wichtig zu zeigen, wie ((vielfältig*)) das Berufsangebot mit einem Studium der Geistes- und Sozialwissenschaften ist. Wenn man zum Beispiel Germanistik studiert, kommen nicht nur Verlagsarbeit oder Journalismus (( in Frage )). Den Blick der Studierenden für andere(( interessante*)) Bereiche zu öffnen, sehen wir als ersten wichtigen ((Schritt)) für die eigene Zukunftsplanung.“ erklärt Julia Protze. (( Mentorin*)) an der Philologischen Fakultät Franziska, Musterstudentin der Germanistik, war ((von)) ihrem Tag in der Stadtverwaltung Geben im Sachgebiet Öffentlichkeitsarbeit begeistert. „Ich fühle mich nun ein wenig sicherer in meinem (( Vorhaben)) , in die Öffentlichkeitsarbeit zu gehen. Susanne Winter hat das Gleiche studiert wie ich und mir meine Fragen ausführlich beantwortet. Außerdem(( durfte)) ich Live miterleben, wie sie einem TV-Team spontan eine Stellungnahme gegeben hat und konnte so gleich einmal sehen, was die Arbeit einer Pressesprecherin alles beinhalten kann. \" Germanistik-Student David war(( zu ))/(Gast) / ( Besuch) an der Bucerius Law School in Hamburg: „Meine Erwartungen wurden definitiv erfüllt. Ich konnte ein paar ehrliche Einschätzungen bekommen. „berichtet er ((voller)) (Begeisterung) (von) seinem Tag mit Alumni Dr. Annette Bärwi. Auch die am Projekt ((beteiligten ))Alumni empfinden den Tag mit den ((Studierenden*)) (als ) Bereicherung. Bereits 25 Alumni aus verschiedenen ((Studiengängen* )) konnten seitdem Projektbeginn für das Programm gewonnen werden. Einige von ihnen hatten schon ( mehrmals )Besuch von einem Studenten oder einer Studentin ihrer Fachrichtung.",
    "passage": "Studierende der Geisteswissenschaften werden oft gefragt ,was sie nach ihrem Studium beruflich einmal machen wollen. Da lohnt sich die Frage, wo denn jene heute arbeiten, die Seminare ,Vorlesungen und Prüfungen bereits erfolgreich hinter sich gelassen haben. Über das Programm „Ein Tag mit \" können Studierende einen Einblick in das Arbeitsleben von Alumni ihres Studienganges bekommen. „Es hat mir viel Mut gemacht zu sehen, dass ich mit meine. Studiengang auf jeden Fall genug Kompetenzen gesammelt / erworben habe, um nach meinem Abschluss einen Job zu bekommen, erzählt Vivienne, die im vierten Master-Semester Anglistik studiert Sie hatim Rahmen von „Ein Tag mit“ der Anglistik-Alumni Magdalena Kaminskat bei ihrer Arbeit als systemischer Coach im Wissenschaftsbereich über die Schulter geschaut. Zusammengeführt wurden beide durch die Mentorinnen der Philologischen Fakultät und das zentrale Alumni Büro der Universität Leipzig. Es ist uns wichtig zu zeigen, wie vielfältig das Berufsangebot mit einem Studium der Geistes- und Sozialwissenschaften ist. Wenn man zum Beispiel Germanistik studiert, kommen nicht nur Verlagsarbeit oder Journalismus in Frage. Den Blick der Studierenden für andereinteressante Bereiche zu öffnen, sehen wir als ersten wichtigen Schritt für die eigene Zukunftsplanung.“ erklärt Julia Protze. Mentorin an der Philologischen Fakultät Franziska, Musterstudentin der Germanistik, war von ihrem Tag in der Stadtverwaltung Geben im Sachgebiet Öffentlichkeitsarbeit begeistert. „Ich fühle mich nun ein wenig sicherer in meinem Vorhaben , in die Öffentlichkeitsarbeit zu gehen. Susanne Winter hat das Gleiche studiert wie ich und mir meine Fragen ausführlich beantwortet. Außerdemdurfte ich Live miterleben, wie sie einem TV-Team spontan eine Stellungnahme gegeben hat und konnte so gleich einmal sehen, was die Arbeit einer Pressesprecherin alles beinhalten kann. \" Germanistik-Student David warzu/Gast / Besuch an der Bucerius Law School in Hamburg: „Meine Erwartungen wurden definitiv erfüllt. Ich konnte ein paar ehrliche Einschätzungen bekommen. „berichtet er voller Begeisterung von seinem Tag mit Alumni Dr. Annette Bärwi. Auch die am Projekt beteiligtenAlumni empfinden den Tag mit den Studierenden als Bereicherung. Bereits 25 Alumni aus verschiedenen Studiengängen konnten seitdem Projektbeginn für das Programm gewonnen werden. Einige von ihnen hatten schon mehrmalsBesuch von einem Studenten oder einer Studentin ihrer Fachrichtung.",
    "chinese": "人文学科的学生经常会被（1）问到，他们毕业以后究竟想从事什么职业。因此，一个值得提 出的问题是：那些已经成功地把研讨课、讲座和考试（2）抛在身后的人，如今都在哪里工 作。通过“一日同行”项目，学生可以（3）深入了解本专业毕业生的职业生活。 “看到自己通过这个专业确实已经（4）获得了足够的能力，能够在毕业后找到一份工作，这给了 我很大的勇气。”正在攻读英语语言文学硕士第四学期的Vivienne说道。 在“一日同行”项目（5）的框架下，她跟随英语专业毕业生Magdalena Kaminska，了解她作为科 学领域（6）系统教练的工作。两人是由莱比锡大学语言文学学院的导师和学校中央校友办公室 （7）联系到一起的。 “对我们来说，重要的是向学生展示，人文和社会科学专业所对应的职业选择是多么（8）多样。 例如，如果学习德语语言文学，那么可以考虑的职业（9）不仅仅是出版社工作或者新闻行业。 我们认为，让学生看到其他（10）有趣的领域，是规划自己未来的重要第一（11）步。”语言文 学学院的（12）导师Julia Protze解释道。 德语语言文学专业的示范学生Franziska对自己（13）在Geben市政府公共关系部门度过的这一天 感到非常满意。“现在，对于进入公共关系行业这一（14）打算，我感觉更有把握了一些。 Susanne Winter和我学的是同一个专业，她非常详细地回答了我的问题。 此外，我还（15）有机会亲眼看到，她如何临时向一个电视团队发表声明，因此我也能够直接 了解新闻发言人的工作究竟可能包括哪些内容。”德语语言文学专业学生David则（16）作为访 客来到了汉堡Bucerius法学院。 “我的期待完全得到了满足。我获得了一些坦诚的评价。”他（17）满怀热情地讲述了自己与校友 Dr. Annette Bärwi共度的一天。参与该项目的校友也认为，与（18）学生共度一天是一种丰富而 有意义的经历。 自项目开始以来，已经有25名来自不同（19）专业的校友加入这一项目。其中一些人以前已经 （20）多次接待过自己专业方向的男学生或女学生。"
