        "chinese": "早在古代，人们就已经提出了事物背后是否存在一种基本体系的问题。当时人们已经认识到， 有些物质彼此之间比其他物质更加相似，并试图（25）从中找出一种秩序。然而，真正具有决 定意义的（26）突破，却是在许多个世纪以后才由俄罗斯化学家德米特里·门捷列夫实现的。他 按照显著的（27）性质和原子量对当时已知的化学元素进行排列，并认识到了其（28）背后的 规律。",
