        "text": "März 1869 [17]____ Mendelejew sein Periodensystem unter dem Titel , Die Abhängigkeit chemischen Eigenschaften der Elemente vom Atomgewicht\".",
        "german": "März 1869 [17]____ Mendelejew sein Periodensystem unter dem Titel , Die Abhängigkeit chemischen Eigenschaften der Elemente vom Atomgewicht\".",
        "chinese": "1869年3月6日，门捷列夫（38）发表了自己的元素周期表，标题为《元素的化学性质对原子量的 依赖关系》。在其中，各种元素（39）组成不同的族，每一族都把具有相似性质的物质纵向排列 在一起。各个族又按照（40）横向的方式排列，使得在各行，也就是所谓的周期中，元素的原子 质量和化合价逐渐增加。 然而，一些例外情况破坏了这种规律。门捷列夫对自己的体系深信不疑，因此对于这些例外，他 只（41）看到了唯一一种解释：它们的原子量一定是被错误测定了。于是，他干脆把一些元素移 到了（42）其他位置。",
