        "chinese": "（32）像微型住宅、共享居住项目和模块化建筑这样的新型居住形式正变得越来越重要。它们不 仅意味着更低的成本和更小的生态足迹，（33）而且还意味着更多的社区共同生活和灵活性。在 共享住宅中，居民共同使用厨房、工作空间和休闲区域——这是一种（34）尤其受到年轻成年人 和数字游民欢迎的居住模式。（35）而微型住宅则可以让人们在极小的空间里过一种极简主义的 生活，而且通常可以移动，并能够实现能源自给。",
